import csv
with open('/data/wenhui/openclaude_rna/rna_harness/data/eterna100_puzzles.tsv') as f:
    r = csv.reader(f, delimiter='\t')
    header = next(r)
    print("cols:", header)
    for row in r:
        if row[0]=='52':
            print("row len:", len(row))
            target = row[3] if len(row)>3 else row[2]
            print("target repr:", repr(target))
            print("len:", len(target))
            # check balance
            stack=[]
            for i,c in enumerate(target):
                if c=='(': stack.append(i)
                elif c==')':
                    if stack: stack.pop()
                    else: print("unmatched close", i)
            print("unmatched opens:", stack)
            break
